def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform divider separating two equally sized panels.
    dividers = []
    for r, row in enumerate(grid):
        if 0 < r < h - 1 and len(set(row)) == 1 and r == h - r - 1:
            dividers.append(("row", r, row[0]))
    for c in range(w):
        if 0 < c < w - 1 and len({grid[r][c] for r in range(h)}) == 1 and c == w - c - 1:
            dividers.append(("col", c, grid[0][c]))

    if not dividers:
        return []

    # Prefer a divider color that occurs nowhere else.
    def score(item):
        axis, pos, color = item
        count = sum(v == color for row in grid for v in row)
        return (count, 0 if axis == "row" else 1)

    axis, pos, _ = min(dividers, key=score)

    if axis == "row":
        first, second = grid[:pos], grid[pos + 1:]
        height, width = len(first), w
        a, b = first, second
    else:
        first = [row[:pos] for row in grid]
        second = [row[pos + 1:] for row in grid]
        height, width = h, len(first[0])
        a, b = first, second

    shared = set(v for row in a for v in row) & set(v for row in b for v in row)
    common = min(shared, key=lambda v: sum(x == v for row in a + b for x in row))

    return [
        [3 if a[i][j] == common and b[i][j] == common else common
         for j in range(width)]
        for i in range(height)
    ]
